var _aMap = [5]uint8{
	0: uint8(SQLITE_ROLLBACK),
	1: uint8(SQLITE_ABORT),
	2: uint8(SQLITE_FAIL),
	3: uint8(SQLITE_IGNORE),
	4: uint8(SQLITE_REPLACE),
}

// C documentation
