	(*(*Tfts5yyStackEntry)(unsafe.Pointer(fts5yypParser + 16))).Fstateno = uint8(0)
	(*(*Tfts5yyStackEntry)(unsafe.Pointer(fts5yypParser + 16))).Fmajor = uint8(0)
