	s = s << int32(7)
	s |= b
	/* s: p0<<21 | p1<<14 | p2<<7 | p3 (masked) */
	p++
	b = b << int32(14)
	b |= uint32(*(*uint8)(unsafe.Pointer(p)))
	/* b: p1<<28 | p3<<14 | p5 (unmasked) */
