	p++
	a = a << int32(15)
	a |= uint32(*(*uint8)(unsafe.Pointer(p)))
	/* a: p4<<29 | p6<<15 | p8 (unmasked) */
	/* moved CSE2 up */
	/* a &= (0x7f<<29)|(0x7f<<15)|(0xff); */
